BOOKINGS=$f bash bin/book A 0800 0900 prev >/dev/null || { echo "boundary before rejected"; fail=1; }
# another room is independent
BOOKINGS=$f bash bin/book B 0900 1000 other >/dev/null || { echo "other room rejected"; fail=1; }
[ "$(wc -l < "$f")" -eq 4 ] || { echo "final count"; fail=1; }
rm -f "$f"
exit $fail

